namespace std {
  class error_code {
  public:
    // Default constructor: Initializes to no error (value = 0, category = generic_category())
    error_code() noexcept;  // Implementation note: Compiler likely inlines this to zero-init members.

    // Parameterized constructor: Sets the error value and category
    error_code(int val, const error_category& cat) noexcept;  // Note: No dynamic allocation; direct assignment of val and cat pointer.

    // Template constructor: Converts enum to error_code using static_cast
    template <class ErrorCodeEnum>  // Compile-time: Requires ErrorCodeEnum to satisfy std::is_error_code_enum<T>
    error_code(ErrorCodeEnum e) noexcept;  // Implementation: Instantiates per enum type, e.g., static_cast<int>(e) for value.
  };
}
